// frontend/src/components/MessageList.js
import React from "react";

export default function MessageList({ messages = [] }) {
  return (
    <div>
      {messages.map(m => (
        <div key={m.id} className={`mb-2 ${m.role === "user" ? "text-end" : ""}`}>
          <div className={`d-inline-block px-3 py-2 rounded ${m.role === "user" ? "bg-primary text-white" : "bg-light text-dark"}`}>
            {m.text}
          </div>
        </div>
      ))}
    </div>
  );
}
